
import type { DeliveryFulfillmentDetails } from './DeliveryFulfillmentDetails.js';
import type { DigitalFulfillmentDetails } from './DigitalFulfillmentDetails.js';
import type { ExpandedPackageSummary } from './ExpandedPackageSummary.js';
import type { ExpandedShipmentSummary } from './ExpandedShipmentSummary.js';
import type { FulfillmentChargeLink } from './FulfillmentChargeLink.js';
import type { FulfillmentLineItem } from './FulfillmentLineItem.js';
import type { FulfillmentRecipient } from './FulfillmentRecipient.js';
import type { PickupFulfillmentDetails } from './PickupFulfillmentDetails.js';
import type { PricingAmounts } from './PricingAmounts.js';
import type { ServiceFulfillmentDetails } from './ServiceFulfillmentDetails.js';
import type { SettlementAmounts } from './SettlementAmounts.js';

export type Fulfillment = { /** Current hold details. While this field is present, status continues to show the public work status from before the hold. */ "active_hold"?: { /** Time the hold became active. Format: date-time. */ "created_at": string; "display_reason"?: string; "held_by"?: string; "reason": "payment_review" | "inventory_issue" | "address_issue" | "customer_request" | "provider_issue" | "scheduling_issue" | "fraud_review" | "other" | (string & {}); "reason_notes"?: string; }; "charges"?: Array<FulfillmentChargeLink>; /** Completion evidence timestamp. Format: date-time. */ "completed_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; "device_id"?: string; "digital_details"?: DigitalFulfillmentDetails; /** First time this fulfillment reached dispatched. Format: date-time. */ "dispatched_at"?: string; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "fulfillment_id": string; "line_items": Array<FulfillmentLineItem>; "local_delivery_details"?: DeliveryFulfillmentDetails; "location_id"?: string; "metadata"?: Record<string, string>; "order"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; "fulfillment_status"?: "not_fulfilled" | "partially_fulfilled" | "fulfilled" | "canceled" | "not_applicable" | "closed" | (string & {}); "order_id": string; "order_number"?: string; "payment_intent_ids"?: Array<string>; "payment_status": "unpaid" | "partially_paid" | "paid" | (string & {}); "pricing_amounts": PricingAmounts; "refund_status": "none" | "partially_refunded" | "refunded" | (string & {}); "settlement_amounts": SettlementAmounts; "status": "open" | "closed" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "order_id": string; /** Terminal outcome details. The mark_no_show action records its reason here and returns status as failed. */ "outcome"?: { "notes"?: string; /** Time the terminal outcome occurred. Format: date-time. */ "occurred_at": string; "outcome_type": "no_show" | (string & {}); "reason": "customer_no_show" | "provider_no_show" | "location_unavailable" | "scheduling_error" | "other" | (string & {}); }; "packages"?: Array<ExpandedPackageSummary>; /** First time this fulfillment reached packed. Format: date-time. */ "packed_at"?: string; /** First time this fulfillment reached picked. Format: date-time. */ "picked_at"?: string; "pickup_details"?: PickupFulfillmentDetails; /** Read-only current quantity accounting behavior for this fulfillment state. */ "quantity_effect"?: "preserve" | "fulfill" | "release" | (string & {}); "recipient"?: FulfillmentRecipient; /** Provider acceptance state, independent from fulfillment work progress. The accept action sets this field to accepted while status remains pending. */ "request_status": "pending" | "accepted" | (string & {}); "service_details"?: ServiceFulfillmentDetails; "shipments"?: Array<ExpandedShipmentSummary>; /** Public work status. Fulfillments with request_status accepted project to status pending. Fulfillments with outcome.outcome_type no_show project to status failed. A fulfillment with active_hold projects to its public work status from before the hold. - `pending`: Work has not started. Start, schedule, accept, hold, cancel, or fail it as supported_actions allows. - `in_progress`: Work has started and is not yet ready or complete. - `ready`: The fulfillment is ready for pickup, handoff, or completion. - `completed`: All fulfillment work completed successfully. - `canceled`: The fulfillment was intentionally canceled and will not continue. - `failed`: The fulfillment could not be completed. Resolve the recorded reason before creating replacement work. - `scheduled`: The fulfillment is scheduled for its recorded service window. - `preparing`: Warehouse or provider preparation is underway. - `picked`: The assigned items have been picked. - `packed`: The assigned items have been packed. - `dispatched`: The fulfillment left its origin for delivery or handoff. */ "status": "pending" | "in_progress" | "ready" | "completed" | "canceled" | "failed" | "scheduled" | "preparing" | "picked" | "packed" | "dispatched" | (string & {}); /** Read-only actions currently supported for this fulfillment. */ "supported_actions": Array<"complete" | "cancel" | "hold" | "start" | "mark_ready" | "fail" | "schedule" | "accept" | "mark_preparing" | "mark_picked" | "mark_packed" | "dispatch" | "mark_no_show" | (string & {})>; /** When the fulfillment entered a terminal state: completed, canceled, or failed. This records the state transition; completed_at records completion evidence supplied for the fulfillment. Format: date-time. */ "terminal_at"?: string; "type": "shipment" | "pickup" | "local_delivery" | "digital" | "service" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; /** Monotonic fulfillment version for expected_version checks. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version": string; };
